-- ============================================================
-- Shahan - catalog seed. Run ONCE in the Supabase SQL Editor
-- (Dashboard -> SQL Editor -> New query -> paste -> Run).
--
-- What this does, in one transaction:
--   1. DELETES the leftover demo products seeded by schema.sql. They are
--      matched on name AND on still carrying a picsum.photos image, so a
--      real product can never be caught by a name collision.
--   2. INSERTS 30 products: trend-led menswear for 2026, each with a
--      written description, real colourways and matching photography.
--
-- Safe to run twice: the insert skips any product whose name already
-- exists, and the delete only ever matches picsum-imaged rows.
--
-- Photography: Pexels (free for commercial use, no attribution
-- required). Images are hotlinked from images.pexels.com. To move them
-- into your own storage bucket, re-upload through the admin panel.
-- ============================================================

begin;

-- ---------- 1. remove the leftover demo catalog ----------

delete from products
 where images::text like '%picsum.photos%'
   and name in (
    'Canvas Crossbody Bag',
    'Cargo Utility Shorts',
    'Color Block Raglan T-Shirt',
    'Corduroy Utility Shirt',
    'Denim Carpenter Shorts',
    'Drawcord Tapered Pants',
    'Jersey Sweat Shorts',
    'Linen Blend Overshirt',
    'Low Top Court Sneakers',
    'Performance Training Tee',
    'Pique Polo Shirt',
    'Piqué Polo Shirt',
    'Pleated Wide Trousers',
    'Ribbed Beanie',
    'Ribbed Collar Polo',
    'Running Joggers',
    'Slip-On Canvas Shoes',
    'Straight Fit Rigid Jeans',
    'Structured Baseball Cap',
    'Suede Chunky Trainers',
    'Tapered Stretch Jeans',
    'Tech Fleece Zip Hoodie',
    'Utility Cargo Trousers',
    'Wide Leg Baggy Jeans',
    'Woven Leather Belt',
    'Zip Placket Knit Polo'
   );

-- ---------- 2. insert the new catalog ----------

with raw (name, cat, fit, price, compare_at, badge, description,
          colors, sizes, images, image_colors, position) as (values
  ('Sundown Oversized Drop-Shoulder Tee', 'tshirts', 'Oversized Fit', 1899, 2499, 'new', 'The silhouette that defines the season. Cut wide through the body with a dropped shoulder seam that sits low on the arm, this heavyweight cotton tee falls with real weight instead of clinging. The washed sage shade is soft and sun-faded from the first wear, and the ribbed crew neck holds its shape wash after wash. Wear it loose over cargos and sneakers, or tucked at the front with wide-leg denim.', '[{"id": "c-5c4eb664-46dd-5b17-8ab6-ebf290c3272c", "name": "Washed Sage", "hex": "#a8bfa4"}, {"id": "c-7ed3c694-c1d9-5cf7-bc23-e0b2d6d5f61c", "name": "Off White", "hex": "#efece5"}, {"id": "c-ca148692-04ec-5d3a-9086-0c80ef02e6a9", "name": "Faded Mint", "hex": "#9fbdb0"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/9225880/pexels-photo-9225880.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/19405826/pexels-photo-19405826.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/20209737/pexels-photo-20209737.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/19405826/pexels-photo-19405826.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/20209737/pexels-photo-20209737.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/9225880/pexels-photo-9225880.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/20209737/pexels-photo-20209737.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/9225880/pexels-photo-9225880.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/19405826/pexels-photo-19405826.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-5c4eb664-46dd-5b17-8ab6-ebf290c3272c"}, {"color": "c-7ed3c694-c1d9-5cf7-bc23-e0b2d6d5f61c"}, {"color": "c-ca148692-04ec-5d3a-9086-0c80ef02e6a9"}, {"color": "c-7ed3c694-c1d9-5cf7-bc23-e0b2d6d5f61c", "main": 0}, {"color": "c-ca148692-04ec-5d3a-9086-0c80ef02e6a9", "main": 0}, {"color": "c-5c4eb664-46dd-5b17-8ab6-ebf290c3272c", "main": 1}, {"color": "c-ca148692-04ec-5d3a-9086-0c80ef02e6a9", "main": 1}, {"color": "c-5c4eb664-46dd-5b17-8ab6-ebf290c3272c", "main": 2}, {"color": "c-7ed3c694-c1d9-5cf7-bc23-e0b2d6d5f61c", "main": 2}]'::jsonb, 31),
  ('Heavyweight Boxy Tee', 'tshirts', 'Boxy Fit', 1699, null, null, 'A proper heavyweight built for people who are tired of tees that go thin after three washes. The boxy body is cut short and square so it sits clean over trousers without bunching, and the dense cotton jersey gives the shoulders real structure. Finished with a double-stitched hem and a ribbed collar that will not stretch out. Offered in deep charcoal and a warm taupe brown that works with almost everything in the wardrobe.', '[{"id": "c-60192f2a-d32c-5c46-ae5f-60f70c6a97c9", "name": "Charcoal", "hex": "#2f2d2b"}, {"id": "c-709928a9-9d38-56a3-a7f5-0fef3c21abee", "name": "Taupe Brown", "hex": "#6b5b50"}, {"id": "c-12e8263a-e699-54db-81d5-91853d27a020", "name": "Black", "hex": "#1a1a1a"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/29276078/pexels-photo-29276078.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/28758242/pexels-photo-28758242.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/8532616/pexels-photo-8532616.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/28758242/pexels-photo-28758242.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/8532616/pexels-photo-8532616.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/29276078/pexels-photo-29276078.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/8532616/pexels-photo-8532616.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/29276078/pexels-photo-29276078.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/28758242/pexels-photo-28758242.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-60192f2a-d32c-5c46-ae5f-60f70c6a97c9"}, {"color": "c-709928a9-9d38-56a3-a7f5-0fef3c21abee"}, {"color": "c-12e8263a-e699-54db-81d5-91853d27a020"}, {"color": "c-709928a9-9d38-56a3-a7f5-0fef3c21abee", "main": 0}, {"color": "c-12e8263a-e699-54db-81d5-91853d27a020", "main": 0}, {"color": "c-60192f2a-d32c-5c46-ae5f-60f70c6a97c9", "main": 1}, {"color": "c-12e8263a-e699-54db-81d5-91853d27a020", "main": 1}, {"color": "c-60192f2a-d32c-5c46-ae5f-60f70c6a97c9", "main": 2}, {"color": "c-709928a9-9d38-56a3-a7f5-0fef3c21abee", "main": 2}]'::jsonb, 32),
  ('Essential Cotton Crew Tee', 'tshirts', 'Regular Fit', 1290, 1690, 'sale', 'The one you will reach for on autopilot. Combed cotton jersey with a smooth face and enough body to hold its shape, cut in a straight regular fit that skims rather than clings. The set-in sleeves and reinforced crew neck keep the lines sharp under a shirt or overshirt, and the plain finish means it layers with anything. Buy the white and the black together and stop thinking about it.', '[{"id": "c-052e9d9b-be47-5cbc-be3b-8fb68cc68ea2", "name": "White", "hex": "#f4f4f2"}, {"id": "c-30694f3d-1278-5883-a2e2-f8553092608c", "name": "Black", "hex": "#1a1a1a"}, {"id": "c-ae662fdb-b0d2-5dce-80e2-f0742607dfd9", "name": "Optic White", "hex": "#fbfbf9"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/8217483/pexels-photo-8217483.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/13185035/pexels-photo-13185035.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/35370174/pexels-photo-35370174.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/13185035/pexels-photo-13185035.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/35370174/pexels-photo-35370174.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/8217483/pexels-photo-8217483.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/35370174/pexels-photo-35370174.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/8217483/pexels-photo-8217483.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/13185035/pexels-photo-13185035.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-052e9d9b-be47-5cbc-be3b-8fb68cc68ea2"}, {"color": "c-30694f3d-1278-5883-a2e2-f8553092608c"}, {"color": "c-ae662fdb-b0d2-5dce-80e2-f0742607dfd9"}, {"color": "c-30694f3d-1278-5883-a2e2-f8553092608c", "main": 0}, {"color": "c-ae662fdb-b0d2-5dce-80e2-f0742607dfd9", "main": 0}, {"color": "c-052e9d9b-be47-5cbc-be3b-8fb68cc68ea2", "main": 1}, {"color": "c-ae662fdb-b0d2-5dce-80e2-f0742607dfd9", "main": 1}, {"color": "c-052e9d9b-be47-5cbc-be3b-8fb68cc68ea2", "main": 2}, {"color": "c-30694f3d-1278-5883-a2e2-f8553092608c", "main": 2}]'::jsonb, 33),
  ('Everyday Relaxed Tee', 'tshirts', 'Relaxed Fit', 1490, null, null, 'A relaxed everyday tee in colours that are easier to wear than plain black. The deep forest green has a soft, slightly washed hand that reads richer in daylight, and the relaxed body gives you room through the chest without looking oversized. Mid-weight cotton keeps it breathable through hot afternoons, and the short sleeves finish just above the elbow. Equally at home under a flannel or on its own with denim.', '[{"id": "c-9747a6d1-25a4-5138-8f54-df9c16e722c8", "name": "Forest Green", "hex": "#2c4636"}, {"id": "c-b4960360-1bf9-5152-be66-02997d0d4921", "name": "Black", "hex": "#1a1a1a"}, {"id": "c-20ef22ed-2939-50ff-a522-6d48b40a33d1", "name": "Jet Black", "hex": "#141414"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/20672939/pexels-photo-20672939.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/9195817/pexels-photo-9195817.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/11992438/pexels-photo-11992438.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/9195817/pexels-photo-9195817.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/11992438/pexels-photo-11992438.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/20672939/pexels-photo-20672939.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/11992438/pexels-photo-11992438.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/20672939/pexels-photo-20672939.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/9195817/pexels-photo-9195817.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-9747a6d1-25a4-5138-8f54-df9c16e722c8"}, {"color": "c-b4960360-1bf9-5152-be66-02997d0d4921"}, {"color": "c-20ef22ed-2939-50ff-a522-6d48b40a33d1"}, {"color": "c-b4960360-1bf9-5152-be66-02997d0d4921", "main": 0}, {"color": "c-20ef22ed-2939-50ff-a522-6d48b40a33d1", "main": 0}, {"color": "c-9747a6d1-25a4-5138-8f54-df9c16e722c8", "main": 1}, {"color": "c-20ef22ed-2939-50ff-a522-6d48b40a33d1", "main": 1}, {"color": "c-9747a6d1-25a4-5138-8f54-df9c16e722c8", "main": 2}, {"color": "c-b4960360-1bf9-5152-be66-02997d0d4921", "main": 2}]'::jsonb, 34),
  ('Wide Stripe Boxy Tee', 'tshirts', 'Boxy Fit', 1799, 2299, 'sale', 'Stripes are back and they are wider than you remember. This boxy tee runs bold horizontal bands across a soft cotton jersey, cut with a short body and a wide chest so it holds the stripe straight instead of warping. Four colourways, from a warm cocoa and cream to a sharp red, a fresh green and a fine navy breton. A single piece that does all the work in an otherwise plain outfit.', '[{"id": "c-fcc85c58-b0ad-52d5-afc2-479a52dce95a", "name": "Cocoa Stripe", "hex": "#8a6a55"}, {"id": "c-56ca7e28-8ea1-59c9-886b-68e3075146bd", "name": "Red Stripe", "hex": "#c0392b"}, {"id": "c-14e1e782-bfa5-5d87-a44a-5091f598082f", "name": "Green Stripe", "hex": "#3f7a52"}, {"id": "c-cdefc6a1-a66c-5ab1-a270-46da126d075b", "name": "Navy Breton", "hex": "#2b3b55"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/19223931/pexels-photo-19223931.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/13404248/pexels-photo-13404248.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/19964737/pexels-photo-19964737.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10762361/pexels-photo-10762361.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/13404248/pexels-photo-13404248.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/19964737/pexels-photo-19964737.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10762361/pexels-photo-10762361.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/19223931/pexels-photo-19223931.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/19964737/pexels-photo-19964737.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10762361/pexels-photo-