  ('Kanji Print Oversized Tee', 'tshirts', 'Oversized Fit', 2199, 2799, 'new', 'Heavy graphic work on a heavy garment. A large-scale print runs across the chest, with Japanese characters set against an illustrated figure and a screen finish that stays matte instead of plasticky. The body is a true oversized cut with a low armhole and a long, straight hem that sits well over baggy denim. Printed on thick cotton so the graphic holds its edges through repeated washing.', '[{"id": "c-740b3205-dba0-5e0c-b63c-154d34710a43", "name": "Black", "hex": "#1a1a1a"}, {"id": "c-fb08d933-9268-5342-9bf5-fe38fac6f73f", "name": "Navy", "hex": "#232b3d"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/36986582/pexels-photo-36986582.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/20772232/pexels-photo-20772232.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/20772232/pexels-photo-20772232.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/36986582/pexels-photo-36986582.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-740b3205-dba0-5e0c-b63c-154d34710a43"}, {"color": "c-fb08d933-9268-5342-9bf5-fe38fac6f73f"}, {"color": "c-fb08d933-9268-5342-9bf5-fe38fac6f73f", "main": 0}, {"color": "c-740b3205-dba0-5e0c-b63c-154d34710a43", "main": 1}]'::jsonb, 36),
  ('Ink Sketch Graphic Tee', 'tshirts', 'Regular Fit', 1899, null, 'new', 'Hand-drawn artwork, printed the way it was drawn. Fine ink linework runs across the front in a loose, sketched style, with enough detail to reward a second look and enough restraint to wear every day. Sits in a straight regular fit on soft cotton jersey with a ribbed crew neck. Available in a clean white that lets the linework breathe and a deep navy that pushes it graphic.', '[{"id": "c-7b3ac88b-29b6-5d79-97f0-bd1ce7e0cd09", "name": "White", "hex": "#f5f4f1"}, {"id": "c-ad46823c-4417-5bd1-a0df-b9a93a1a6ae2", "name": "Navy", "hex": "#26314d"}, {"id": "c-91291b52-9d12-5ee5-adbd-0628907ef857", "name": "Chalk White", "hex": "#faf9f6"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/2451200/pexels-photo-2451200.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/14428671/pexels-photo-14428671.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/6048171/pexels-photo-6048171.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/14428671/pexels-photo-14428671.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/6048171/pexels-photo-6048171.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/2451200/pexels-photo-2451200.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/6048171/pexels-photo-6048171.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/2451200/pexels-photo-2451200.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/14428671/pexels-photo-14428671.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-7b3ac88b-29b6-5d79-97f0-bd1ce7e0cd09"}, {"color": "c-ad46823c-4417-5bd1-a0df-b9a93a1a6ae2"}, {"color": "c-91291b52-9d12-5ee5-adbd-0628907ef857"}, {"color": "c-ad46823c-4417-5bd1-a0df-b9a93a1a6ae2", "main": 0}, {"color": "c-91291b52-9d12-5ee5-adbd-0628907ef857", "main": 0}, {"color": "c-7b3ac88b-29b6-5d79-97f0-bd1ce7e0cd09", "main": 1}, {"color": "c-91291b52-9d12-5ee5-adbd-0628907ef857", "main": 1}, {"color": "c-7b3ac88b-29b6-5d79-97f0-bd1ce7e0cd09", "main": 2}, {"color": "c-ad46823c-4417-5bd1-a0df-b9a93a1a6ae2", "main": 2}]'::jsonb, 37),
  ('Long Sleeve Crew Tee', 'tshirts', 'Regular Fit', 1990, 2490, 'sale', 'The layering piece that carries you from a cool morning into a warm afternoon. Cut long in the body and the sleeve on a mid-weight cotton knit, with ribbed cuffs that hold at the wrist rather than riding up. Wear it on its own, under a short-sleeve shirt, or beneath an overshirt when the temperature drops. Three colours: a deep teal blue, a soft dusty pink, and a fine navy stripe.', '[{"id": "c-079c85c8-aa7b-572c-99e3-50de0db6621d", "name": "Teal Blue", "hex": "#3b6478"}, {"id": "c-43aec12d-7d91-5093-8456-993bfa86ba00", "name": "Dusty Pink", "hex": "#d98f9a"}, {"id": "c-059f0a78-27db-540d-a49c-5a74bbcfd1e8", "name": "Navy Stripe", "hex": "#2f3a4c"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/20849170/pexels-photo-20849170.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/4518029/pexels-photo-4518029.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/24770057/pexels-photo-24770057.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/4518029/pexels-photo-4518029.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/24770057/pexels-photo-24770057.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/20849170/pexels-photo-20849170.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/24770057/pexels-photo-24770057.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/20849170/pexels-photo-20849170.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/4518029/pexels-photo-4518029.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-079c85c8-aa7b-572c-99e3-50de0db6621d"}, {"color": "c-43aec12d-7d91-5093-8456-993bfa86ba00"}, {"color": "c-059f0a78-27db-540d-a49c-5a74bbcfd1e8"}, {"color": "c-43aec12d-7d91-5093-8456-993bfa86ba00", "main": 0}, {"color": "c-059f0a78-27db-540d-a49c-5a74bbcfd1e8", "main": 0}, {"color": "c-079c85c8-aa7b-572c-99e3-50de0db6621d", "main": 1}, {"color": "c-059f0a78-27db-540d-a49c-5a74bbcfd1e8", "main": 1}, {"color": "c-079c85c8-aa7b-572c-99e3-50de0db6621d", "main": 2}, {"color": "c-43aec12d-7d91-5093-8456-993bfa86ba00", "main": 2}]'::jsonb, 38),
  ('Cuban Collar Camp Shirt', 'shirts', 'Relaxed Fit', 2690, 3290, 'new', 'The open Cuban collar is the detail that makes a plain shirt look considered. Cut relaxed through the body with a straight hem designed to be worn out, this camp shirt sits flat against the collarbone and stays cool when everything else feels heavy. The oatmeal is a quiet, textured neutral; the palm print is the one people ask about. Both wear open over a plain tee or buttoned on their own.', '[{"id": "c-eb34f2c7-6547-5cb6-99cb-4bfc0997f595", "name": "Oatmeal", "hex": "#cfc4b0"}, {"id": "c-965040b6-6b37-5e53-8343-cf0e1393855a", "name": "Palm Print Blue", "hex": "#5b7d94"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/18153495/pexels-photo-18153495.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/9880321/pexels-photo-9880321.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/9880321/pexels-photo-9880321.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/18153495/pexels-photo-18153495.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-eb34f2c7-6547-5cb6-99cb-4bfc0997f595"}, {"color": "c-965040b6-6b37-5e53-8343-cf0e1393855a"}, {"color": "c-965040b6-6b37-5e53-8343-cf0e1393855a", "main": 0}, {"color": "c-eb34f2c7-6547-5cb6-99cb-4bfc0997f595", "main": 1}]'::jsonb, 39),
  ('Grandad Collar Linen Shirt', 'shirts', 'Regular Fit', 3290, 3990, 'new', 'Pure linen, band collar, no fuss. The collarless grandad neckline keeps the line clean at the throat and the natural linen slub gives the fabric a texture that photographs beautifully and gets softer with every wash. Cut in a regular fit with a half placket and a straight hem, it works rolled at the sleeve with trousers or worn loose over shorts. Linen creases; that is the point.', '[{"id": "c-8ce35630-604f-5609-aed1-02618aa1e85b", "name": "Natural Linen", "hex": "#e2dbca"}, {"id": "c-b854684e-a49d-5fc7-bdee-f62a2edef451", "name": "Cream", "hex": "#efe9dd"}, {"id": "c-2c743706-c9c0-5fb7-9054-dd2b9fce3422", "name": "White", "hex": "#f7f5ef"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/22441297/pexels-photo-22441297.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/22441291/pexels-photo-22441291.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17805751/pexels-photo-17805751.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/22441291/pexels-photo-22441291.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17805751/pexels-photo-17805751.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/22441297/pexels-photo-22441297.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17805751/pexels-photo-17805751.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/22441297/pexels-photo-22441297.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/22441291/pexels-photo-22441291.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-8ce35630-604f-5609-aed1-02618aa1e85b"}, {"color": "c-b854684e-a49d-5fc7-bdee-f62a2edef451"}, {"color": "c-2c743706-c9c0-5fb7-9054-dd2b9fce3422"}, {"color": "c-b854684e-a49d-5fc7-bdee-f62a2edef451", "main": 0}, {"color": "c-2c743706-c9c0-5fb7-9054-dd2b9fce3422", "main": 0}, {"color": "c-8ce35630-604f-5609-aed1-02618aa1e85b", "main": 1}, {"color": "c-2c743706-c9c0-5fb7-9054-dd2b9fce3422", "main": 1}, {"color": "c-8ce35630-604f-5609-aed1-02618aa1e85b", "main": 2}, {"color": "c-b854684e-a49d-5fc7-bdee-f62a2edef451", "main": 2}]'::jsonb, 40),
  ('Relaxed Linen Shirt', 'shirts', 'Relaxed Fit', 3190, null, null, 'A full-sleeve linen shirt cut with room to move. The relaxed body drapes away from the chest instead of pulling across it, and the breathable linen weave keeps air moving on the hottest days. A standard point collar and a curved hem mean it works tucked or loose, sleeves rolled to the elbow. The sage and teal are the standouts; the white is the one you will wear most.', '[{"id": "c-8f3a30d5-1824-5016-ba46-08490196bf4c", "name": "Sage", "hex": "#8fa085"}, {"id": "c-361fd233-b10b-5146-8acc-f8eef9a60189", "name": "Teal", "hex": "#2f6f7e"}, {"id": "c-2dbfc558-aa43-5fff-a17f-558c2b7bc307", "name": "White", "hex": "#f2efe8"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/5156489/pexels-photo-5156489.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/8053518/pexels-photo-8053518.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17718224/pexels-photo-17718224.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/8053518/pexels-photo-8053518.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17718224/pexels-photo-17718224.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/5156489/pexels-photo-5156489.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17718224/pexels-photo-17718224.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/5156489/pexels-photo-5156489.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/8053518/pexels-photo-8053518.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-8f3a30d5-1824-5016-ba46-08490196bf4c"}, {"color": "c-361fd233-b10b-5146-8acc-f8eef9a60189"}, {"color": "c-2dbfc558-aa43-5fff-a17f-558c2b7bc307"}, {"color": "c-361fd233-b10b-5146-8acc-f8eef9a60189", "main": 0}, {"color": "c-2dbfc558-aa43-5fff-a17f-558c2b7bc307", "main": 0}, {"color": "c-8f3a30d5-1824-5016-ba46-08490196bf4c", "main": 1}, {"color": "c-2dbfc558-aa43-5fff-a17f-558c2b7bc307", "main": 1}, {"color": "c-8f3a30d5-1824-5016-ba46-08490196bf4c", "main": 2}, {"color": "c-361fd233-b10b-5146-8acc-f8eef9a60189", "main": 2}]'::jsonb, 41),
  ('Oxford Button-Down Shirt', 'shirts', 'Regular Fit', 2890, null, null, 'The most useful shirt in menswear, made properly. Woven oxford cotton with a soft button-down collar that rolls rather than sits flat, cut regular through the chest with a curved hem for tucking. Smart enough for an office, relaxed enough with sleeves pushed up and denim. Comes in clean white, a soft dusty pink, and a fine vertical stripe for when plain feels too plain.', '[{"id": "c-935b8cee-ac1d-5997-b8d4-fd326d1b202c", "name": "White", "hex": "#f6f5f2"}, {"id": "c-6c0b4ff5-b54e-565c-9078-0bdad3c62ca0", "name": "Dusty Pink", "hex": "#e0a3a3"}, {"id": "c-6a44d68f-2ec6-511b-bd36-922b749631ee", "name": "Fine Stripe", "hex": "#dfdcd4"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/15185872/pexels-photo-15185872.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/9025139/pexels-photo-9025139.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/12871416/pexels-photo-12871416.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/9025139/pexels-photo-9025139.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/12871416/pexels-photo-12871416.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/15185872/pexels-photo-15185872.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/12871416/pexels-photo-12871416.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/15185872/pexels-photo-15185872.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/9025139/pexels-photo-9025139.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-935b8cee-ac1d-5997-b8d4-fd326d1b202c"}, {"color": "c-6c0b4ff5-b54e-565c-9078-0bdad3c62ca0"}, {"color": "c-6a44d68f-2ec6-511b-bd36-922b749631ee"}, {"color": "c-6c0b4ff5-b54e-565c-9078-0bdad3c62ca0", "main": 0}, {"color": "c-6a44d68f-2ec6-511b-bd36-922b749631ee", "main": 0}, {"color": "c-935b8cee-ac1d-5997-b8d4-fd326d1b202c", "main": 1}, {"color": "c-6a44d68f-2ec6-511b-bd36-922b749631ee", "main": 1}, {"color": "c-935b8cee-ac1d-5997-b8d4-fd326d1b202c", "main": 2}, {"color": "c-6c0b4ff5-b54e-565c-9078-0bdad3c62ca0", "main": 2}]'::jsonb, 42),
  ('Flannel Check Overshirt', 'shirts', 'Boxy Fit', 3490, 4290, 'sale', 'Half shirt, half light jacket, and the single most useful layer for transitional weather. Brushed cotton flannel with a soft napped face, cut boxy and slightly long so it sits over a tee without riding up. Chest pockets, a full button front, and a heavier weight than a standard shirt. Three checks: a deep burgundy and navy plaid, a warm brown and rust, and a graphic black and cream buffalo.', '[{"id": "c-30c2ab97-0b3a-5ec3-b3f0-8ca210a22ca1", "name": "Burgundy Check", "hex": "#6e2f3a"}, {"id": "c-5263d863-e5bb-5c30-81a8-e6d35c87da92", "name": "Rust Check", "hex": "#7a4a2e"}, {"id": "c-4784ae9d-0e3b-5ae4-9b4d-38ac0fe3a986", "name": "Buffalo Check", "hex": "#2b2b2b"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/7284986/pexels-photo-7284986.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/33587249/pexels-photo-33587249.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/11118747/pexels-photo-11118747.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/33587249/pexels-photo-33587249.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/11118747/pexels-photo-11118747.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/7284986/pexels-photo-7284986.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/11118747/pexels-photo-11118747.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/7284986/pexels-photo-7284986.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/33587249/pexels-photo-33587249.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-30c2ab97-0b3a-5ec3-b3f0-8ca210a22ca1"}, {"color": "c-5263d863-e5bb-5c30-81a8-e6d35c87da92"}, {"color": "c-4784ae9d-0e3b-5ae4-9b4d-38ac0fe3a986"}, {"color": "c-5263d863-e5bb-5c30-81a8-e6d35c87da92", "main": 0}, {"color": "c-4784ae9d-0e3b-5ae4-9b4d-38ac0fe3a986", "main": 0}, {"color": "c-30c2ab97-0b3a-5ec3-b3f0-8ca210a22ca1", "main": 1}, {"color": "c-4784ae9d-0e3b-5ae4-9b4d-38ac0fe3a986", "main": 1}, {"color": "c-30c2ab97-0b3a-5ec3-b3f0-8ca210a22ca1", "main": 2}, {"color": "c-5263d863-e5bb-5c30-81a8-e6d35c87da92", "main": 2}]'::jsonb, 43),
  ('Washed Denim Shirt', 'shirts', 'Regular Fit', 3290, null, 'new', 'Denim you can wear on your top half without it feeling like a jacket. Woven from a lighter-weight cotton denim and given a soft enzyme wash, so it arrives broken in rather than stiff. A regular fit with a point collar, chest pockets, and a curved hem. Wear it buttoned as a shirt or open over a white tee as an overshirt; the washed grey blue is the quietest of the three.', '[{"id": "c-1b258446-6f61-51e3-9167-2017eba5a5d4", "name": "Bright Blue", "hex": "#3d7fa6"}, {"id": "c-32ca7abf-a811-5e45-b1df-8cfad7cdb1b1", "name": "Cobalt", "hex": "#2c4f8f"}, {"id": "c-d0533d10-e236-5730-8b70-134db05fe337", "name": "Washed Grey Blue", "hex": "#7d8b96"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/9522507/pexels-photo-9522507.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/37631699/pexels-photo-37631699.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/26859209/pexels-photo-26859209.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/37631699/pexels-photo-37631699.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/26859209/pexels-photo-26859209.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/9522507/pexels-photo-9522507.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/26859209/pexels-photo-26859209.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/9522507/pexels-photo-9522507.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/37631699/pexels-photo-37631699.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-1b258446-6f61-51e3-9167-2017eba5a5d4"}, {"color": "c-32ca7abf-a811-5e45-b1df-8cfad7cdb1b1"}, {"color": "c-d0533d10-e236-5730-8b70-134db05fe337"}, {"color": "c-32ca7abf-a811-5e45-b1df-8cfad7cdb1b1", "main": 0}, {"color": "c-d0533d10-e236-5730-8b70-134db05fe337", "main": 0}, {"color": "c-1b258446-6f61-51e3-9167-2017eba5a5d4", "main": 1}, {"color": "c-d0533d10-e236-5730-8b70-134db05fe337", "main": 1}, {"color": "c-1b258446-6f61-51e3-9167-2017eba5a5d4", "main": 2}, {"color": "c-32ca7abf-a811-5e45-b1df-8cfad7cdb1b1", "main": 2}]'::jsonb, 44),
  ('Textured Knit Polo', 'polos', 'Regular Fit', 2490, 2990, 'new', 'The knitted polo is the piece that has quietly taken over smart-casual dressing, and this is the version to own. Fine-gauge knit with a visible texture that catches the light, a soft unstructured collar that stays down on its own, and a short two-button placket. Heavier and more luxurious than a standard pique. The powder blue is easy; the vertical stripes are the ones that get noticed.', '[{"id": "c-7b3436c8-6c80-5c55-8832-a6f914eeb6e4", "name": "Powder Blue", "hex": "#8fb4cf"}, {"id": "c-acbd2a5d-7582-5eec-b101-4ba913dc0357", "name": "Charcoal Stripe", "hex": "#3a3a38"}, {"id": "c-069bf889-8e46-54dc-a3aa-61a1636e0c51", "name": "Cream Stripe", "hex": "#e6e0d4"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/17089178/pexels-photo-17089178.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10962177/pexels-photo-10962177.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17781293/pexels-photo-17781293.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10962177/pexels-photo-10962177.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17781293/pexels-photo-17781293.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17089178/pexels-photo-17089178.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17781293/pexels-photo-17781293.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17089178/pexels-photo-17089178.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10962177/pexels-photo-10962177.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-7b3436c8-6c80-5c55-8832-a6f914eeb6e4"}, {"color": "c-acbd2a5d-7582-5eec-b101-4ba913dc0357"}, {"color": "c-069bf889-8e46-54dc-a3aa-61a1636e0c51"}, {"color": "c-acbd2a5d-7582-5eec-b101-4ba913dc0357", "main": 0}, {"color": "c-069bf889-8e46-54dc-a3aa-61a1636e0c51", "main": 0}, {"color": "c-7b3436c8-6c80-5c55-8832-a6f914eeb6e4", "main": 1}, {"color": "c-069bf889-8e46-54dc-a3aa-61a1636e0c51", "main": 1}, {"color": "c-7b3436c8-6c80-5c55-8832-a6f914eeb6e4", "main": 2}, {"color": "c-acbd2a5d-7582-5eec-b101-4ba913dc0357", "main": 2}]'::jsonb, 45),
  ('Classic Pique Polo', 'polos', 'Regular Fit', 1799, 2299, 'sale', 'The polo everything else is measured against. Breathable cotton pique with the honeycomb texture that keeps it cool and stops it clinging, a ribbed collar with enough body to stand up, and a three-button placket. Regular fit through the chest with ribbed sleeve cuffs. Three colours that cover every situation: a clean cream, a deep maroon, and a soft marl grey.', '[{"id": "c-5d6caa2c-d645-5aaa-9315-31aa74cc5b67", "name": "Cream", "hex": "#e8e3d6"}, {"id": "c-6dd9f07f-9ff9-5b3d-b0a0-03563480e7e7", "name": "Maroon", "hex": "#7d2130"}, {"id": "c-2b4a7897-b5ae-58e5-ba0b-e6afcbe5b065", "name": "Marl Grey", "hex": "#a9adaf"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/17898548/pexels-photo-17898548.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/13133287/pexels-photo-13133287.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17984122/pexels-photo-17984122.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/13133287/pexels-photo-13133287.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17984122/pexels-photo-17984122.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17898548/pexels-photo-17898548.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17984122/pexels-photo-17984122.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17898548/pexels-photo-17898548.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/13133287/pexels-photo-13133287.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-5d6caa2c-d645-5aaa-9315-31aa74cc5b67"}, {"color": "c-6dd9f07f-9ff9-5b3d-b0a0-03563480e7e7"}, {"color": "c-2b4a7897-b5ae-58e5-ba0b-e6afcbe5b065"}, {"color": "c-6dd9f07f-9ff9-5b3d-b0a0-03563480e7e7", "main": 0}, {"color": "c-2b4a7897-b5ae-58e5-ba0b-e6afcbe5b065", "main": 0}, {"color": "c-5d6caa2c-d645-5aaa-9315-31aa74cc5b67", "main": 1}, {"color": "c-2b4a7897-b5ae-58e5-ba0b-e6afcbe5b065", "main": 1}, {"color": "c-5d6caa2c-d645-5aaa-9315-31aa74cc5b67", "main": 2}, {"color": "c-6dd9f07f-9ff9-5b3d-b0a0-03563480e7e7", "main": 2}]'::jsonb, 46),
  ('Oversized Boxy Polo', 'polos', 'Oversized Fit', 2290, null, 'new', 'The polo, rebuilt on a streetwear frame. Cut oversized and boxy with a dropped shoulder and a wide, short body, so it wears more like a knitted tee than a golf shirt. The soft collar sits open and relaxed and the sleeve finishes wide at the bicep. In muted stone and sage that suit the loose silhouette. Wear it with wide trousers and it does most of the outfit for you.', '[{"id": "c-e04194c1-075b-5c7c-86dd-a453682caeea", "name": "Stone", "hex": "#b8ada0"}, {"id": "c-72f714ad-bda9-554f-a620-585a2abf7f5a", "name": "Sage Grey", "hex": "#9fa693"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/26063373/pexels-photo-26063373.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17898556/pexels-photo-17898556.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17898556/pexels-photo-17898556.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/26063373/pexels-photo-26063373.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-e04194c1-075b-5c7c-86dd-a453682caeea"}, {"color": "c-72f714ad-bda9-554f-a620-585a2abf7f5a"}, {"color": "c-72f714ad-bda9-554f-a620-585a2abf7f5a", "main": 0}, {"color": "c-e04194c1-075b-5c7c-86dd-a453682caeea", "main": 1}]'::jsonb, 47),
  ('Slim Fit Cotton Polo', 'polos', 'Slim Fit', 1699, null, null, 'A cleaner, closer polo for when the oversized cut is too much. Cut slim through the chest and arm on a smooth cotton knit, with a flat collar and a short placket that sits neat when open. It tucks cleanly into chinos and layers under a jacket without bulk. Navy for the safe bet, cream for warm weather, grey for everything in between.', '[{"id": "c-2ffd6493-2108-5e99-a0c2-21381d0c9c81", "name": "Navy", "hex": "#26314d"}, {"id": "c-e2b0b5ed-45e0-50fc-b6fc-483a1a697d02", "name": "Cream", "hex": "#e5dfd2"}, {"id": "c-f3549cd6-82ed-501c-9d41-a9e769249c70", "name": "Grey", "hex": "#9b9fa2"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/15994973/pexels-photo-15994973.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/6256848/pexels-photo-6256848.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/33651005/pexels-photo-33651005.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/6256848/pexels-photo-6256848.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/33651005/pexels-photo-33651005.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/15994973/pexels-photo-15994973.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/33651005/pexels-photo-33651005.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/15994973/pexels-photo-15994973.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/6256848/pexels-photo-6256848.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-2ffd6493-2108-5e99-a0c2-21381d0c9c81"}, {"color": "c-e2b0b5ed-45e0-50fc-b6fc-483a1a697d02"}, {"color": "c-f3549cd6-82ed-501c-9d41-a9e769249c70"}, {"color": "c-e2b0b5ed-45e0-50fc-b6fc-483a1a697d02", "main": 0}, {"color": "c-f3549cd6-82ed-501c-9d41-a9e769249c70", "main": 0}, {"color": "c-2ffd6493-2108-5e99-a0c2-21381d0c9c81", "main": 1}, {"color": "c-f3549cd6-82ed-501c-9d41-a9e769249c70", "main": 1}, {"color": "c-2ffd6493-2108-5e99-a0c2-21381d0c9c81", "main": 2}, {"color": "c-e2b0b5ed-45e0-50fc-b6fc-483a1a697d02", "main": 2}]'::jsonb, 48),
  ('Relaxed Straight Jeans', 'jeans', 'Straight Fit', 3690, 4490, 'sale', 'Straight, roomy and nothing like the skinny jeans everyone spent a decade in. Cut with a comfortable seat and thigh, then falling dead straight from the knee to a full break over the shoe. Made from a mid-weight cotton denim with just enough give to sit comfortably through a long day. The light wash is the summer pair; the indigo is the one that will age best.', '[{"id": "c-9c1b52e9-8a7a-5de4-a90b-53c80b39dc50", "name": "Light Wash", "hex": "#9fb8cf"}, {"id": "c-c03fccee-c220-5158-a212-45e61c555ea9", "name": "Sky Wash", "hex": "#8fadc9"}, {"id": "c-c3240cd0-ea5f-5cc8-9e62-e402341e290f", "name": "Indigo", "hex": "#2d3f63"}]'::jsonb, '["30", "32", "34", "36", "38"]'::jsonb, '["https://images.pexels.com/photos/16069736/pexels-photo-16069736.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/2244954/pexels-photo-2244954.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10133274/pexels-photo-10133274.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/2244954/pexels-photo-2244954.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10133274/pexels-photo-10133274.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/16069736/pexels-photo-16069736.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10133274/pexels-photo-10133274.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/16069736/pexels-photo-16069736.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/2244954/pexels-photo-2244954.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-9c1b52e9-8a7a-5de4-a90b-53c80b39dc50"}, {"color": "c-c03fccee-c220-5158-a212-45e61c555ea9"}, {"color": "c-c3240cd0-ea5f-5cc8-9e62-e402341e290f"}, {"color": "c-c03fccee-c220-5158-a212-45e61c555ea9", "main": 0}, {"color": "c-c3240cd0-ea5f-5cc8-9e62-e402341e290f", "main": 0}, {"color": "c-9c1b52e9-8a7a-5de4-a90b-53c80b39dc50", "main": 1}, {"color": "c-c3240cd0-ea5f-5cc8-9e62-e402341e290f", "main": 1}, {"color": "c-9c1b52e9-8a7a-5de4-a90b-53c80b39dc50", "main": 2}, {"color": "c-c03fccee-c220-5158-a212-45e61c555ea9", "main": 2}]'::jsonb, 49),
  ('Distressed Light Wash Jeans', 'jeans', 'Relaxed Fit', 4290, null, 'new', 'Lightweight, pale and deliberately worn in. The distressing is placed by hand at the knee and thigh so it reads lived-in rather than manufactured, and the near-white wash keeps the whole pair light enough for hot weather. Cut relaxed through the leg with a straight opening that stacks slightly over a sneaker. Pair with a plain heavy tee and let the denim do the talking.', '[{"id": "c-bcf51f95-43f1-56ed-be54-4b58372e464d", "name": "Bone Wash", "hex": "#dcdad4"}, {"id": "c-2acc3344-ca73-5039-90bc-6b99f1ca4f1a", "name": "Pale Grey Wash", "hex": "#c8c6c1"}, {"id": "c-5409d8d5-2fc3-5d9c-98b4-14d5dab7605f", "name": "Vintage White", "hex": "#e6e4de"}]'::jsonb, '["30", "32", "34", "36", "38"]'::jsonb, '["https://images.pexels.com/photos/17459735/pexels-photo-17459735.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17459740/pexels-photo-17459740.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17459774/pexels-photo-17459774.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17459740/pexels-photo-17459740.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17459774/pexels-photo-17459774.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17459735/pexels-photo-17459735.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17459774/pexels-photo-17459774.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17459735/pexels-photo-17459735.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17459740/pexels-photo-17459740.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-bcf51f95-43f1-56ed-be54-4b58372e464d"}, {"color": "c-2acc3344-ca73-5039-90bc-6b99f1ca4f1a"}, {"color": "c-5409d8d5-2fc3-5d