  ('Black Tapered Jeans', 'jeans', 'Tapered Fit', 3490, null, null, 'Black denim solves problems. Cut with a regular seat and thigh, then tapered cleanly from the knee so it finishes narrow at the ankle without gripping the calf. The deep black is a proper garment dye that resists fading to grey, and the mid-weight stretch denim moves with you. The single easiest way to make a plain tee and sneakers look intentional.', '[{"id": "c-a69a76ef-26ec-5518-8d33-13a9e812993d", "name": "Jet Black", "hex": "#161616"}, {"id": "c-a909d88c-5fd0-5e6b-ad7a-82798ed2871b", "name": "Washed Black", "hex": "#2b2b2d"}, {"id": "c-88a60e01-f7a7-514b-96fc-9eb0986b8ab2", "name": "Deep Black", "hex": "#101010"}]'::jsonb, '["30", "32", "34", "36", "38"]'::jsonb, '["https://images.pexels.com/photos/19971478/pexels-photo-19971478.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/2229712/pexels-photo-2229712.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/30407915/pexels-photo-30407915.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/2229712/pexels-photo-2229712.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/30407915/pexels-photo-30407915.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/19971478/pexels-photo-19971478.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/30407915/pexels-photo-30407915.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/19971478/pexels-photo-19971478.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/2229712/pexels-photo-2229712.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-a69a76ef-26ec-5518-8d33-13a9e812993d"}, {"color": "c-a909d88c-5fd0-5e6b-ad7a-82798ed2871b"}, {"color": "c-88a60e01-f7a7-514b-96fc-9eb0986b8ab2"}, {"color": "c-a909d88c-5fd0-5e6b-ad7a-82798ed2871b", "main": 0}, {"color": "c-88a60e01-f7a7-514b-96fc-9eb0986b8ab2", "main": 0}, {"color": "c-a69a76ef-26ec-5518-8d33-13a9e812993d", "main": 1}, {"color": "c-88a60e01-f7a7-514b-96fc-9eb0986b8ab2", "main": 1}, {"color": "c-a69a76ef-26ec-5518-8d33-13a9e812993d", "main": 2}, {"color": "c-a909d88c-5fd0-5e6b-ad7a-82798ed2871b", "main": 2}]'::jsonb, 51),
  ('Indigo Straight Jeans', 'jeans', 'Straight Fit', 3990, 4790, 'sale', 'Deep indigo denim with a dry, rigid hand that softens into the shape of whoever wears it. Cut straight from hip to hem on a heavier cotton twill, with reinforced pocket bags and copper-tone hardware. The indigo starts almost blue-black and fades honestly at the knee and seat over the first year. A pair to keep, not to replace every season.', '[{"id": "c-fa1131cb-b97b-52c1-8e0b-9ae11bd54614", "name": "Raw Indigo", "hex": "#26375c"}, {"id": "c-5a05fb0c-2da1-5b79-82f9-12a3180660a1", "name": "Mid Blue", "hex": "#4a6d94"}, {"id": "c-f03a21f5-c383-5bab-9481-ccd6775b218b", "name": "Stone Wash", "hex": "#93a9be"}]'::jsonb, '["30", "32", "34", "36", "38"]'::jsonb, '["https://images.pexels.com/photos/10133275/pexels-photo-10133275.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/4258605/pexels-photo-4258605.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/14840593/pexels-photo-14840593.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/4258605/pexels-photo-4258605.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/14840593/pexels-photo-14840593.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10133275/pexels-photo-10133275.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/14840593/pexels-photo-14840593.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10133275/pexels-photo-10133275.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/4258605/pexels-photo-4258605.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-fa1131cb-b97b-52c1-8e0b-9ae11bd54614"}, {"color": "c-5a05fb0c-2da1-5b79-82f9-12a3180660a1"}, {"color": "c-f03a21f5-c383-5bab-9481-ccd6775b218b"}, {"color": "c-5a05fb0c-2da1-5b79-82f9-12a3180660a1", "main": 0}, {"color": "c-f03a21f5-c383-5bab-9481-ccd6775b218b", "main": 0}, {"color": "c-fa1131cb-b97b-52c1-8e0b-9ae11bd54614", "main": 1}, {"color": "c-f03a21f5-c383-5bab-9481-ccd6775b218b", "main": 1}, {"color": "c-fa1131cb-b97b-52c1-8e0b-9ae11bd54614", "main": 2}, {"color": "c-5a05fb0c-2da1-5b79-82f9-12a3180660a1", "main": 2}]'::jsonb, 52),
  ('Pleated Wide Leg Trousers', 'trousers', 'Wide Fit', 3490, 4190, 'new', 'Pleats are what separate a trouser from a pant. Twin pleats at the waistband release into a wide, straight leg that falls in a clean column and moves when you do. Cut high on the waist on a structured cotton twill that holds the pleat without pressing. The rust is a statement, the camel is the versatile one, and the stone goes with everything already in the wardrobe.', '[{"id": "c-9507ea99-c1f5-5d6b-bfcc-62158d2aae5e", "name": "Rust", "hex": "#b4552a"}, {"id": "c-4b406454-6ac0-575e-8610-76cd29999dc7", "name": "Camel", "hex": "#b0894f"}, {"id": "c-dfafe0c2-939b-59ae-829f-5ac5820c583d", "name": "Stone", "hex": "#c3b49a"}]'::jsonb, '["30", "32", "34", "36", "38"]'::jsonb, '["https://images.pexels.com/photos/10341113/pexels-photo-10341113.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/18817925/pexels-photo-18817925.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/16238583/pexels-photo-16238583.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/18817925/pexels-photo-18817925.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/16238583/pexels-photo-16238583.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10341113/pexels-photo-10341113.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/16238583/pexels-photo-16238583.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10341113/pexels-photo-10341113.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/18817925/pexels-photo-18817925.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-9507ea99-c1f5-5d6b-bfcc-62158d2aae5e"}, {"color": "c-4b406454-6ac0-575e-8610-76cd29999dc7"}, {"color": "c-dfafe0c2-939b-59ae-829f-5ac5820c583d"}, {"color": "c-4b406454-6ac0-575e-8610-76cd29999dc7", "main": 0}, {"color": "c-dfafe0c2-939b-59ae-829f-5ac5820c583d", "main": 0}, {"color": "c-9507ea99-c1f5-5d6b-bfcc-62158d2aae5e", "main": 1}, {"color": "c-dfafe0c2-939b-59ae-829f-5ac5820c583d", "main": 1}, {"color": "c-9507ea99-c1f5-5d6b-bfcc-62158d2aae5e", "main": 2}, {"color": "c-4b406454-6ac0-575e-8610-76cd29999dc7", "main": 2}]'::jsonb, 53),
  ('Relaxed Tapered Chinos', 'trousers', 'Tapered Fit', 2890, null, null, 'The chino, given room where it matters. Relaxed through the seat and thigh, then tapered from the knee to a clean ankle finish, so it reads modern without becoming skinny. Cotton twill with a slight brushed hand and a touch of stretch, plus slanted side pockets and a curtained waistband. Olive khaki, tobacco brown and pale stone: three neutrals that quietly do everything.', '[{"id": "c-40dd92d1-65be-5c64-ab97-28996c5236ee", "name": "Olive Khaki", "hex": "#8a8468"}, {"id": "c-6932210d-1da3-5381-8d3d-c1d1f119aec1", "name": "Tobacco", "hex": "#7a5334"}, {"id": "c-bd7ceaaa-f312-51ca-b7c8-920cbd793997", "name": "Pale Stone", "hex": "#cbbca4"}]'::jsonb, '["30", "32", "34", "36", "38"]'::jsonb, '["https://images.pexels.com/photos/9464625/pexels-photo-9464625.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/21327844/pexels-photo-21327844.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/19974898/pexels-photo-19974898.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/21327844/pexels-photo-21327844.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/19974898/pexels-photo-19974898.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/9464625/pexels-photo-9464625.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/19974898/pexels-photo-19974898.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/9464625/pexels-photo-9464625.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/21327844/pexels-photo-21327844.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-40dd92d1-65be-5c64-ab97-28996c5236ee"}, {"color": "c-6932210d-1da3-5381-8d3d-c1d1f119aec1"}, {"color": "c-bd7ceaaa-f312-51ca-b7c8-920cbd793997"}, {"color": "c-6932210d-1da3-5381-8d3d-c1d1f119aec1", "main": 0}, {"color": "c-bd7ceaaa-f312-51ca-b7c8-920cbd793997", "main": 0}, {"color": "c-40dd92d1-65be-5c64-ab97-28996c5236ee", "main": 1}, {"color": "c-bd7ceaaa-f312-51ca-b7c8-920cbd793997", "main": 1}, {"color": "c-40dd92d1-65be-5c64-ab97-28996c5236ee", "main": 2}, {"color": "c-6932210d-1da3-5381-8d3d-c1d1f119aec1", "main": 2}]'::jsonb, 54),
  ('Cargo Utility Trousers', 'trousers', 'Loose Fit', 3290, 3990, 'sale', 'Real cargo trousers, with pockets deep enough to actually use. Cut loose through the leg with bellowed thigh pockets, a reinforced knee panel and a drawcord hem you can cinch over a boot. Made from a hard-wearing cotton ripstop that gets softer without losing structure. Military olive is the original; khaki and sand are the easier daily wears.', '[{"id": "c-fc78e0b4-0f41-5b49-bcf5-924752bd9c4e", "name": "Military Olive", "hex": "#5c6247"}, {"id": "c-33b3e7fb-683e-544f-b428-8c23f6674ae4", "name": "Khaki", "hex": "#a89474"}, {"id": "c-c1692291-a7af-512d-bff8-8f914f2fb12c", "name": "Sand", "hex": "#d3c0a0"}]'::jsonb, '["30", "32", "34", "36", "38"]'::jsonb, '["https://images.pexels.com/photos/11716436/pexels-photo-11716436.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/21050240/pexels-photo-21050240.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/18393526/pexels-photo-18393526.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/21050240/pexels-photo-21050240.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/18393526/pexels-photo-18393526.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/11716436/pexels-photo-11716436.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/18393526/pexels-photo-18393526.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/11716436/pexels-photo-11716436.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/21050240/pexels-photo-21050240.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-fc78e0b4-0f41-5b49-bcf5-924752bd9c4e"}, {"color": "c-33b3e7fb-683e-544f-b428-8c23f6674ae4"}, {"color": "c-c1692291-a7af-512d-bff8-8f914f2fb12c"}, {"color": "c-33b3e7fb-683e-544f-b428-8c23f6674ae4", "main": 0}, {"color": "c-c1692291-a7af-512d-bff8-8f914f2fb12c", "main": 0}, {"color": "c-fc78e0b4-0f41-5b49-bcf5-924752bd9c4e", "main": 1}, {"color": "c-c1692291-a7af-512d-bff8-8f914f2fb12c", "main": 1}, {"color": "c-fc78e0b4-0f41-5b49-bcf5-924752bd9c4e", "main": 2}, {"color": "c-33b3e7fb-683e-544f-b428-8c23f6674ae4", "main": 2}]'::jsonb, 55),
  ('Everyday Stone Trousers', 'trousers', 'Relaxed Fit', 2790, null, null, 'A soft, easy trouser for days that do not need denim. Relaxed through the leg with a gentle taper, an elasticated back waistband for comfort, and a cotton twill light enough for warm weather. The cropped hem sits just above the sneaker so the shoe stays visible. Stone, olive and pale grey, all chosen to sit under a plain tee without a second thought.', '[{"id": "c-da879b47-e713-5ea8-936f-95468e24c7b0", "name": "Stone", "hex": "#cfc5b0"}, {"id": "c-9184e311-5dd8-5ab1-95f0-7e618b069959", "name": "Olive", "hex": "#5f6a4f"}, {"id": "c-013ea264-ccb5-5310-b68a-d62e9c0ef60d", "name": "Pale Grey", "hex": "#c3c6cc"}]'::jsonb, '["30", "32", "34", "36", "38"]'::jsonb, '["https://images.pexels.com/photos/29547631/pexels-photo-29547631.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/4066289/pexels-photo-4066289.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17082930/pexels-photo-17082930.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/4066289/pexels-photo-4066289.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17082930/pexels-photo-17082930.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/29547631/pexels-photo-29547631.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/17082930/pexels-photo-17082930.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/29547631/pexels-photo-29547631.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/4066289/pexels-photo-4066289.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-da879b47-e713-5ea8-936f-95468e24c7b0"}, {"color": "c-9184e311-5dd8-5ab1-95f0-7e618b069959"}, {"color": "c-013ea264-ccb5-5310-b68a-d62e9c0ef60d"}, {"color": "c-9184e311-5dd8-5ab1-95f0-7e618b069959", "main": 0}, {"color": "c-013ea264-ccb5-5310-b68a-d62e9c0ef60d", "main": 0}, {"color": "c-da879b47-e713-5ea8-936f-95468e24c7b0", "main": 1}, {"color": "c-013ea264-ccb5-5310-b68a-d62e9c0ef60d", "main": 1}, {"color": "c-da879b47-e713-5ea8-936f-95468e24c7b0", "main": 2}, {"color": "c-9184e311-5dd8-5ab1-95f0-7e618b069959", "main": 2}]'::jsonb, 56),
  ('Heavyweight Fleece Hoodie', 'activewear', 'Oversized Fit', 3990, 4990, 'sale', 'A serious hoodie with the weight to prove it. Brushed cotton fleece with a dense loopback interior, cut oversized with a dropped shoulder and a wide body that holds its shape instead of collapsing. A double-layer hood that actually stands up, ribbed cuffs and hem, and a kangaroo pocket set low. Warm sand, deep charcoal and a soft powder blue.', '[{"id": "c-f3e2c7ae-fa1d-5847-b7bc-417b968a692e", "name": "Sand", "hex": "#d9b899"}, {"id": "c-311c2135-985e-5023-86d1-74cb4dc92b15", "name": "Charcoal", "hex": "#3a3d40"}, {"id": "c-734d843e-4d65-5396-9e22-8e38e8d3a75f", "name": "Powder Blue", "hex": "#a9cfe0"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/10887703/pexels-photo-10887703.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/30257616/pexels-photo-30257616.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/2314992/pexels-photo-2314992.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/30257616/pexels-photo-30257616.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/2314992/pexels-photo-2314992.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10887703/pexels-photo-10887703.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/2314992/pexels-photo-2314992.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/10887703/pexels-photo-10887703.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/30257616/pexels-photo-30257616.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-f3e2c7ae-fa1d-5847-b7bc-417b968a692e"}, {"color": "c-311c2135-985e-5023-86d1-74cb4dc92b15"}, {"color": "c-734d843e-4d65-5396-9e22-8e38e8d3a75f"}, {"color": "c-311c2135-985e-5023-86d1-74cb4dc92b15", "main": 0}, {"color": "c-734d843e-4d65-5396-9e22-8e38e8d3a75f", "main": 0}, {"color": "c-f3e2c7ae-fa1d-5847-b7bc-417b968a692e", "main": 1}, {"color": "c-734d843e-4d65-5396-9e22-8e38e8d3a75f", "main": 1}, {"color": "c-f3e2c7ae-fa1d-5847-b7bc-417b968a692e", "main": 2}, {"color": "c-311c2135-985e-5023-86d1-74cb4dc92b15", "main": 2}]'::jsonb, 57),
  ('Relaxed Sweat Joggers', 'activewear', 'Relaxed Fit', 2490, null, 'new', 'Joggers cut for lounging and for leaving the house. Relaxed through the thigh with a tapered leg and a ribbed cuff that gathers cleanly at the ankle, on a brushed-back cotton fleece that stays soft against the skin. Drawcord waistband, deep side pockets and a heavier weight than the usual sweatpant. Pair them with the fleece hoodie for a full set.', '[{"id": "c-2eb17732-9b75-5dfd-9319-76c687f30038", "name": "Pistachio", "hex": "#c7d3a6"}, {"id": "c-28b4ae08-280e-5881-9f52-df3044b2b2b1", "name": "Heather Grey", "hex": "#a5a5a3"}, {"id": "c-020e8656-4704-5735-8968-1df3bfb6a76d", "name": "Burnt Orange", "hex": "#d1481f"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/4611660/pexels-photo-4611660.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/31961168/pexels-photo-31961168.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/34272485/pexels-photo-34272485.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/31961168/pexels-photo-31961168.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/34272485/pexels-photo-34272485.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/4611660/pexels-photo-4611660.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/34272485/pexels-photo-34272485.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/4611660/pexels-photo-4611660.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/31961168/pexels-photo-31961168.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-2eb17732-9b75-5dfd-9319-76c687f30038"}, {"color": "c-28b4ae08-280e-5881-9f52-df3044b2b2b1"}, {"color": "c-020e8656-4704-5735-8968-1df3bfb6a76d"}, {"color": "c-28b4ae08-280e-5881-9f52-df3044b2b2b1", "main": 0}, {"color": "c-020e8656-4704-5735-8968-1df3bfb6a76d", "main": 0}, {"color": "c-2eb17732-9b75-5dfd-9319-76c687f30038", "main": 1}, {"color": "c-020e8656-4704-5735-8968-1df3bfb6a76d", "main": 1}, {"color": "c-2eb17732-9b75-5dfd-9319-76c687f30038", "main": 2}, {"color": "c-28b4ae08-280e-5881-9f52-df3044b2b2b1", "main": 2}]'::jsonb, 58),
  ('Cotton Twill Shorts', 'shorts', 'Regular Fit', 1890, 2390, 'sale', 'Shorts that hold a line instead of flapping. Woven from a mid-weight cotton twill with just enough structure to sit flat, cut to finish just above the knee with a clean side-seam pocket and a single back welt. No drawcord, no elastic, no sag. White and cream for the warm months, black for when you want it to disappear.', '[{"id": "c-7d4fa449-5d01-5082-8ad5-789c0bb9bd9a", "name": "White", "hex": "#f2f0eb"}, {"id": "c-c7d41727-84f8-5b88-ba17-00d7566bc115", "name": "Cream", "hex": "#e6dfd0"}, {"id": "c-7264d1e5-b5bf-5314-bed8-ab7ea55dde69", "name": "Black", "hex": "#1c1c1c"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/18178451/pexels-photo-18178451.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/18178103/pexels-photo-18178103.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/28038671/pexels-photo-28038671.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/18178103/pexels-photo-18178103.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/28038671/pexels-photo-28038671.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/18178451/pexels-photo-18178451.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/28038671/pexels-photo-28038671.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/18178451/pexels-photo-18178451.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/18178103/pexels-photo-18178103.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-7d4fa449-5d01-5082-8ad5-789c0bb9bd9a"}, {"color": "c-c7d41727-84f8-5b88-ba17-00d7566bc115"}, {"color": "c-7264d1e5-b5bf-5314-bed8-ab7ea55dde69"}, {"color": "c-c7d41727-84f8-5b88-ba17-00d7566bc115", "main": 0}, {"color": "c-7264d1e5-b5bf-5314-bed8-ab7ea55dde69", "main": 0}, {"color": "c-7d4fa449-5d01-5082-8ad5-789c0bb9bd9a", "main": 1}, {"color": "c-7264d1e5-b5bf-5314-bed8-ab7ea55dde69", "main": 1}, {"color": "c-7d4fa449-5d01-5082-8ad5-789c0bb9bd9a", "main": 2}, {"color": "c-c7d41727-84f8-5b88-ba17-00d7566bc115", "main": 2}]'::jsonb, 59),
  ('Relaxed Denim Shorts', 'shorts', 'Relaxed Fit', 2290, null, 'new', 'Denim shorts, cut long enough to be wearable. A relaxed leg finishing just on the knee, made from a lighter-weight cotton denim so they breathe through the afternoon, with a five-pocket build and a clean turned hem. The light wash is the everyday pair; the white is the one for hot weather and sandals.', '[{"id": "c-f7411e62-3f65-523a-82b7-9b5cea041e45", "name": "Light Wash", "hex": "#8fa3b8"}, {"id": "c-9d091870-eaf5-58c9-93df-2791ea300a41", "name": "White Denim", "hex": "#eceae4"}]'::jsonb, '["S", "M", "L", "XL", "XXL"]'::jsonb, '["https://images.pexels.com/photos/13015120/pexels-photo-13015120.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/30710156/pexels-photo-30710156.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/30710156/pexels-photo-30710156.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop", "https://images.pexels.com/photos/13015120/pexels-photo-13015120.jpeg?auto=compress&cs=tinysrgb&w=640&h=854&fit=crop"]'::jsonb, '[{"color": "c-f7411e62-3f65-523a-82b7-9b5cea041e45"}, {"color": "c-9d091870-eaf5-58c9-93df-2791ea300a41"}, {"color": "c-9d091870-eaf5-58c9-93df-2791ea300a41", "main": 0}, {"color": "c-f7411e62-3f65-523a-82b7-9b5cea041e45", "main": 1}]'::jsonb, 60)
)
insert into products (name, category_slug, fit, dept, price, compare_at, badge,
                      sold_out, description, colors, sizes, images, image_colors,
                      active, position)
select r.name, r.cat, r.fit, 'MEN', r.price, r.compare_at, r.badge,
       false, r.description, r.colors, r.sizes, r.images, r.image_colors,
       true, r.position
  from raw r
 where not exists (select 1 from products p where p.name = r.name);

commit;

